namespace sv_23a83946a93b4bf28a65a5d84764322e.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = ["Dr. Smith", "Dr. Johnson", "Dr. Williams", "Dr. Brown"];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return fixed slots regardless of doctor/date
        var slots = new List<string> { "9:00 AM", "10:00 AM", "11:00 AM", "1:00 PM", "2:00 PM", "3:00 PM" };
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient data against server-side business rules.
    /// Returns a dictionary of field name → error messages. Empty means valid.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject outstanding-balance email
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = ["Account has outstanding balance"];
        }

        // Reject self-pay with doctor who doesn't accept it
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients"];
        }

        // Simulate race-condition on time slot
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_23a83946a93b4bf28a65a5d84764322e.Services;

public class AppointmentModel : IValidatableObject
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    // Step 2
    public string? Doctor { get; set; }

    public DateTime? AppointmentDate { get; set; }

    public string? TimeSlot { get; set; }

    public string? ReasonForVisit { get; set; }

    /// <summary>
    /// Controls which step-level validation runs. Set by the page before manual Validate() calls.
    /// </summary>
    public int ValidatingStep { get; set; } = 1;

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (ValidatingStep < 2)
        {
            yield break;
        }

        if (string.IsNullOrWhiteSpace(Doctor))
        {
            yield return new ValidationResult("Please select a doctor.", [nameof(Doctor)]);
        }

        if (AppointmentDate is null)
        {
            yield return new ValidationResult("Appointment date is required.", [nameof(AppointmentDate)]);
        }
        else if (AppointmentDate.Value.Date <= DateTime.Today)
        {
            yield return new ValidationResult("Appointment date must be in the future.", [nameof(AppointmentDate)]);
        }

        if (string.IsNullOrWhiteSpace(TimeSlot))
        {
            yield return new ValidationResult("Please select a time slot.", [nameof(TimeSlot)]);
        }

        if (string.IsNullOrWhiteSpace(ReasonForVisit))
        {
            yield return new ValidationResult("Reason for visit is required.", [nameof(ReasonForVisit)]);
        }
        else if (ReasonForVisit.Length > 500)
        {
            yield return new ValidationResult("Reason for visit must be 500 characters or fewer.", [nameof(ReasonForVisit)]);
        }
    }
}

