@using sv_23a83946a93b4bf28a65a5d84764322e.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <ServerValidator @ref="serverValidator" />

    @* ── STEP 1 ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Next")
        </button>
    }

    @* ── STEP 2 ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="appointmentDate">Date</label>
                <InputDate id="appointmentDate" class="form-control" @bind-Value="Model.AppointmentDate" @bind:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" maxlength="500" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>
        </fieldset>

        <div class="mt-3 d-flex gap-2">
            <button type="button" class="btn btn-secondary" @onclick="BackToStep1">Back</button>
            <button type="submit" class="btn btn-success" disabled="@isProcessing">
                @(isProcessing ? "Submitting..." : "Check Availability & Book")
            </button>
        </div>
    }
</EditForm>

@if (isBooked)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model = new();
    private EditContext editContext = default!;
    private ServerValidator? serverValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        serverValidator?.ClearErrors();

        // Validate only step-1 fields
        Model.ValidatingStep = 1;
        if (!editContext.Validate())
        {
            return;
        }

        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        Model.TimeSlot = null;
        availableSlots = [];

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverValidator?.ClearErrors();
    }

    private async Task HandleSubmit()
    {
        serverValidator?.ClearErrors();

        // Full validation (step 1 + step 2)
        Model.ValidatingStep = 2;
        if (!editContext.Validate())
        {
            return;
        }

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (errors.Count > 0)
            {
                serverValidator!.DisplayErrors(errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    /// <summary>
    /// Lightweight component that adds server-returned errors to the EditContext
    /// so they appear next to the matching ValidationMessage components.
    /// </summary>
    private sealed class ServerValidator : ComponentBase
    {
        [CascadingParameter]
        private EditContext? EditContext { get; set; }

        private ValidationMessageStore? messageStore;

        protected override void OnInitialized()
        {
            messageStore = new ValidationMessageStore(EditContext!);
            EditContext!.OnValidationRequested += (_, _) => messageStore.Clear();
            EditContext!.OnFieldChanged += (_, e) => messageStore.Clear(e.FieldIdentifier);
        }

        public void DisplayErrors(Dictionary<string, List<string>> errors)
        {
            foreach (var (field, messages) in errors)
            {
                foreach (var message in messages)
                {
                    messageStore!.Add(EditContext!.Field(field), message);
                }
            }
            EditContext!.NotifyValidationStateChanged();
        }

        public void ClearErrors()
        {
            messageStore?.Clear();
            EditContext?.NotifyValidationStateChanged();
        }
    }
}

